    for (int32_t i = 0; i < 8; ++i) {
        double bin_width = (double)(s.max_val + 1) / 8.0;
        int32_t lo = (int32_t)(i * bin_width);
        int32_t hi = (i == 7) ? s.max_val : (int32_t)((i + 1) * bin_width) - 1;
        std::println(os, "  [{:3d},{:3d}]: {}", lo, hi, s.histogram[i]);
    }
}

