        auto parsed = parse_args_new(args);
        if (!parsed)
            return std::unexpected(parsed.error());
        return ParseResult{.args = *parsed};
    }

    auto parsed = parse_args_old(args);
    if (!parsed)
        return std::unexpected(parsed.error());
    return ParseResult{.args = *parsed};
}

} // namespace raster::gen

