int main(int argc, char** argv) {
    std::vector<std::string_view> args;
    args.reserve(argc);
    for (int i = 0; i < argc; ++i)
        args.emplace_back(argv[i]);

    auto result = parse_args(args);
    if (!result) [[unlikely]] {
        switch (result.error()) {
        case ParseError::kNoArg:
