    uint16_t _max_val;
    std::int64_t _capacity = 0;
    std::int64_t _total = 0;
    bool _header_written = false;
    int32_t _col = 0;

    PpmWriteResult put(uint8_t r, uint8_t g, uint8_t b);
};

} // namespace raster::common

