    } else {
        std::print(_os, " {:3d} {:3d} {:3d}", static_cast<int>(r), static_cast<int>(g),
                   static_cast<int>(b));
    }
    ++_col;
    ++_total;
    if (_col >= _width) {
        std::println(_os);
        _col = 0;
    }
    if (_os.bad() || _os.fail())
        return PpmWriteResult{std::unexpected(PpmWriteError::kIOError),
                              "сбой записи пикселя в поток"};

    return PpmWriteResult{};
}
